"use strict";App.Pages.JitsiSettings=function(){function isInvalid(){try{return $("#jitsi-settings .is-invalid").removeClass("is-invalid"),!1}catch(error){return App.Layouts.Backend.displayNotification(error.message),!0}}function deserialize(jitsiSettings){jitsiSettings.forEach(function(jitsiSetting){var $field=$("[data-field=\""+jitsiSetting.name+"\"]");$field.is(":checkbox")?$field.prop("checked",!!+jitsiSetting.value):$field.val(jitsiSetting.value)})}function serialize(){var jitsiSettings=[];return $("[data-field]").each(function(index,field){var $field=$(field);jitsiSettings.push({name:$field.data("field"),value:$field.is(":checkbox")?+$field.prop("checked"):$field.val()})}),jitsiSettings}function onSaveSettingsClick(){if(isInvalid())return void App.Layouts.Backend.displayNotification(lang("settings_are_invalid"));var jitsiSettings=serialize();App.Http.JitsiSettings.save(jitsiSettings).done(function(){App.Layouts.Backend.displayNotification(lang("settings_saved"))})}var $saveSettings=$("#save-settings");return document.addEventListener("DOMContentLoaded",function(){$saveSettings.on("click",onSaveSettingsClick);var jitsiSettings=vars("jitsi_settings");deserialize(jitsiSettings)}),{}}();